-- The SQL 6502.  GENERATED by sql65/gencore.py from sql65/isa.py -- edit those.
--
-- The whole machine: a dense memory table, a decode table (the instruction
-- set as data), a one-row cpu latch, and a clock.  Stepping is INSERT INTO
-- clock; the trigger executes exactly one instruction in exactly one
-- UPDATE, then applies its (up to three) memory writes.

CREATE TABLE memory (
    addr INTEGER PRIMARY KEY,
    v    INTEGER NOT NULL CHECK (v BETWEEN 0 AND 255)
);
WITH RECURSIVE n(i) AS (SELECT 0 UNION ALL SELECT i + 1 FROM n WHERE i < 65535)
INSERT INTO memory SELECT i, 0 FROM n;

-- the tick source for batch runs: INSERT INTO clock SELECT n FROM ticks WHERE n < ?
CREATE TABLE ticks (n INTEGER PRIMARY KEY);
WITH RECURSIVE n(i) AS (SELECT 0 UNION ALL SELECT i + 1 FROM n WHERE i < 65535)
INSERT INTO ticks SELECT i FROM n;

-- op -> how to fetch (len, mode, reads), what to compute (kind), where it
-- goes (dst bitmask A=1 X=2 Y=4 S=8, sp delta, ctl for the PC, wr for memory)
CREATE TABLE decode (
    op       INTEGER PRIMARY KEY,
    len      INTEGER NOT NULL,
    mode     INTEGER NOT NULL,
    reads    INTEGER NOT NULL,
    sp       INTEGER NOT NULL,
    ctl      INTEGER NOT NULL,
    kind     INTEGER NOT NULL,
    dst      INTEGER NOT NULL,
    wr       INTEGER NOT NULL,
    mnemonic TEXT    NOT NULL
);
