-- the latch: architectural registers, bookkeeping, and this instruction's writes
CREATE TABLE cpu (
    id     INTEGER PRIMARY KEY CHECK (id = 1),
    pc     INTEGER NOT NULL,
    a      INTEGER NOT NULL,
    x      INTEGER NOT NULL,
    y      INTEGER NOT NULL,
    s      INTEGER NOT NULL,
    p      INTEGER NOT NULL,
    ipc    INTEGER NOT NULL,   -- address of the instruction just executed
    op     INTEGER NOT NULL,   -- its opcode
    steps  INTEGER NOT NULL,
    halted INTEGER NOT NULL,   -- the PC pinned itself: the ROMs' trap signal
    ea     INTEGER,            -- the data address the instruction used
    hit    INTEGER,            -- the watched address it touched, if any: the platform hook
    w0a INTEGER, w0v INTEGER,
    w1a INTEGER, w1v INTEGER,
    w2a INTEGER, w2v INTEGER,
    CHECK ((w0a IS NULL) = (w0v IS NULL)),
    CHECK ((w1a IS NULL) = (w1v IS NULL)),
    CHECK ((w2a IS NULL) = (w2v IS NULL))
);
INSERT INTO cpu VALUES (1, 0, 0, 0, 0, 0xFD, 0x24, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

-- the platform hook: addresses whose access (io) or write (wr) stops a run
CREATE TABLE watch (id INTEGER PRIMARY KEY CHECK (id = 1), io_lo INTEGER NOT NULL, io_hi INTEGER NOT NULL,
                    wr_lo INTEGER NOT NULL, wr_hi INTEGER NOT NULL);
INSERT INTO watch VALUES (1, -1, -2, -1, -2);

CREATE VIEW trace AS
    SELECT cpu.*, decode.mnemonic FROM cpu JOIN decode ON decode.op = cpu.op;

CREATE TABLE clock (t INTEGER);

-- One instruction per tick.  Fetch, decode, address and operand are joins
-- (NULL keys cost nothing); the result is one packed word
-- (memory half << 16 | new P << 8 | result byte) chosen by kind; the
-- selectors route it.  A fault leaves the row untouched, PC on the opcode.
CREATE TRIGGER step BEFORE INSERT ON clock
BEGIN
  UPDATE OR FAIL cpu SET (ipc, op, pc, steps, halted, a, x, y, s, p, w0a, w0v, w1a, w1v, w2a, w2v, ea, hit) = (
    SELECT ipc, op, npc, cpu.steps + 1, (npc = ipc),
      CASE WHEN dst & 1 THEN res & 0xFF ELSE cpu.a END,
      CASE WHEN dst & 2 THEN res & 0xFF ELSE cpu.x END,
      CASE WHEN dst & 4 THEN res & 0xFF ELSE cpu.y END,
      (((CASE WHEN dst & 8 THEN res & 0xFF ELSE cpu.s END) + sp) & 0xFF),
      ((res >> 8) & 0xFF),
      CASE wr
      WHEN 1 THEN ea  -- result byte to ea
      WHEN 2 THEN ea  -- memory half to ea
      WHEN 3 THEN (0x100 + cpu.s)  -- push
      WHEN 4 THEN (0x100 + cpu.s)  -- JSR
      WHEN 5 THEN (0x100 + cpu.s)  -- BRK
      WHEN 6 THEN (CASE WHEN (((ea) - (cpu.y)) & 0xFF) + (cpu.y) > 0xFF THEN (((((((((ea) - (cpu.y)) & 0xFFFF) >> 8)) & (cpu.x)) << 8) + (((ea) - (cpu.y)) & 0xFF) + (cpu.y)) & 0xFFFF) ELSE ea END)  -- SHA/SHX
      WHEN 7 THEN (CASE WHEN (((ea) - (cpu.x)) & 0xFF) + (cpu.x) > 0xFF THEN (((((((((ea) - (cpu.x)) & 0xFFFF) >> 8)) & (cpu.y)) << 8) + (((ea) - (cpu.x)) & 0xFF) + (cpu.x)) & 0xFFFF) ELSE ea END)  -- SHY
      WHEN 8 THEN (CASE WHEN (((ea) - (cpu.y)) & 0xFF) + (cpu.y) > 0xFF THEN (((((((((ea) - (cpu.y)) & 0xFFFF) >> 8)) & (((cpu.a) & (cpu.x)))) << 8) + (((ea) - (cpu.y)) & 0xFF) + (cpu.y)) & 0xFFFF) ELSE ea END)  -- TAS
    END,
      CASE wr
      WHEN 1 THEN (res & 0xFF)  -- 
      WHEN 2 THEN ((res >> 16) & 0xFF)  -- 
      WHEN 3 THEN (res & 0xFF)  -- 
      WHEN 4 THEN (((ipc + 2) & 0xFFFF) >> 8)  -- 
      WHEN 5 THEN (((ipc + 2) & 0xFFFF) >> 8)  -- 
      WHEN 6 THEN (res & 0xFF)  -- 
      WHEN 7 THEN (res & 0xFF)  -- 
      WHEN 8 THEN ((res >> 16) & 0xFF)  -- 
    END,
      CASE wr
      WHEN 4 THEN (0x100 + ((cpu.s - 1) & 0xFF))  -- JSR
      WHEN 5 THEN (0x100 + ((cpu.s - 1) & 0xFF))  -- BRK
    END,
      CASE wr
      WHEN 4 THEN (((ipc + 2) & 0xFFFF) & 0xFF)  -- 
      WHEN 5 THEN (((ipc + 2) & 0xFFFF) & 0xFF)  -- 
    END,
      CASE wr
      WHEN 5 THEN (0x100 + ((cpu.s - 2) & 0xFF))  -- BRK
    END,
      CASE wr
      WHEN 5 THEN (cpu.p | 0x30)  -- BRK pushes P with B and bit 5 set
    END,
      ea,
      CASE WHEN ea BETWEEN io_lo AND io_hi THEN ea WHEN (CASE wr
      WHEN 1 THEN ea  -- result byte to ea
      WHEN 2 THEN ea  -- memory half to ea
      WHEN 3 THEN (0x100 + cpu.s)  -- push
      WHEN 4 THEN (0x100 + cpu.s)  -- JSR
      WHEN 5 THEN (0x100 + cpu.s)  -- BRK
      WHEN 6 THEN (CASE WHEN (((ea) - (cpu.y)) & 0xFF) + (cpu.y) > 0xFF THEN (((((((((ea) - (cpu.y)) & 0xFFFF) >> 8)) & (cpu.x)) << 8) + (((ea) - (cpu.y)) & 0xFF) + (cpu.y)) & 0xFFFF) ELSE ea END)  -- SHA/SHX
      WHEN 7 THEN (CASE WHEN (((ea) - (cpu.x)) & 0xFF) + (cpu.x) > 0xFF THEN (((((((((ea) - (cpu.x)) & 0xFFFF) >> 8)) & (cpu.y)) << 8) + (((ea) - (cpu.x)) & 0xFF) + (cpu.x)) & 0xFFFF) ELSE ea END)  -- SHY
      WHEN 8 THEN (CASE WHEN (((ea) - (cpu.y)) & 0xFF) + (cpu.y) > 0xFF THEN (((((((((ea) - (cpu.y)) & 0xFFFF) >> 8)) & (((cpu.a) & (cpu.x)))) << 8) + (((ea) - (cpu.y)) & 0xFF) + (cpu.y)) & 0xFFFF) ELSE ea END)  -- TAS
    END) BETWEEN wr_lo AND wr_hi THEN (CASE wr
      WHEN 1 THEN ea  -- result byte to ea
      WHEN 2 THEN ea  -- memory half to ea
      WHEN 3 THEN (0x100 + cpu.s)  -- push
      WHEN 4 THEN (0x100 + cpu.s)  -- JSR
      WHEN 5 THEN (0x100 + cpu.s)  -- BRK
      WHEN 6 THEN (CASE WHEN (((ea) - (cpu.y)) & 0xFF) + (cpu.y) > 0xFF THEN (((((((((ea) - (cpu.y)) & 0xFFFF) >> 8)) & (cpu.x)) << 8) + (((ea) - (cpu.y)) & 0xFF) + (cpu.y)) & 0xFFFF) ELSE ea END)  -- SHA/SHX
      WHEN 7 THEN (CASE WHEN (((ea) - (cpu.x)) & 0xFF) + (cpu.x) > 0xFF THEN (((((((((ea) - (cpu.x)) & 0xFFFF) >> 8)) & (cpu.y)) << 8) + (((ea) - (cpu.x)) & 0xFF) + (cpu.x)) & 0xFFFF) ELSE ea END)  -- SHY
      WHEN 8 THEN (CASE WHEN (((ea) - (cpu.y)) & 0xFF) + (cpu.y) > 0xFF THEN (((((((((ea) - (cpu.y)) & 0xFFFF) >> 8)) & (((cpu.a) & (cpu.x)))) << 8) + (((ea) - (cpu.y)) & 0xFF) + (cpu.y)) & 0xFFFF) ELSE ea END)  -- TAS
    END) END
    FROM (
      SELECT g.*,
        CASE kind
      WHEN 0 THEN (((0) << 16) | ((cpu.p) << 8) | ((0) & 0xFF))  -- BR
      WHEN 1 THEN (((0) << 16) | (((((cpu.p) & 0x7D) | (CASE WHEN (val) = 0 THEN 2 ELSE 0 END) | ((val) & 0x80))) << 8) | ((val) & 0xFF))  -- LDA
      WHEN 2 THEN (((0) << 16) | ((cpu.p) << 8) | ((0) & 0xFF))  -- NOP
      WHEN 3 THEN (((0) << 16) | (((((cpu.p) & 0x7C) | (CASE WHEN ((((cpu.a) - (val)) & 0xFF)) = 0 THEN 2 ELSE 0 END) | (CASE WHEN (val) <= (cpu.a) THEN 1 ELSE 0 END) | (((((cpu.a) - (val)) & 0xFF)) & 0x80))) << 8) | ((0) & 0xFF))  -- CMP
      WHEN 4 THEN (((0) << 16) | ((cpu.p) << 8) | ((0) & 0xFF))  -- JSR
      WHEN 5 THEN (((0) << 16) | ((cpu.p) << 8) | ((0) & 0xFF))  -- RTS
      WHEN 6 THEN (((0) << 16) | ((cpu.p) << 8) | ((cpu.a) & 0xFF))  -- STA
      WHEN 7 THEN (((0) << 16) | (((((cpu.p) & 0x3D) | (CASE WHEN (((cpu.a) & (val))) = 0 THEN 2 ELSE 0 END) | ((val) & 0xC0))) << 8) | ((0) & 0xFF))  -- BIT
      WHEN 8 THEN (((0) << 16) | (((((cpu.p) & 0x7D) | (CASE WHEN ((((cpu.y) + 1) & 0xFF)) = 0 THEN 2 ELSE 0 END) | (((((cpu.y) + 1) & 0xFF)) & 0x80))) << 8) | (((((cpu.y) + 1) & 0xFF)) & 0xFF))  -- INY
      WHEN 9 THEN (((0) << 16) | ((((cpu.p) | 0x01)) << 8) | ((0) & 0xFF))  -- SEC
      WHEN 10 THEN (((0) << 16) | (((((cpu.p) & 0x7D) | (CASE WHEN (val) = 0 THEN 2 ELSE 0 END) | ((val) & 0x80))) << 8) | ((val) & 0xFF))  -- LDY
      WHEN 11 THEN (((0) << 16) | ((((cpu.p) & 0xFE)) << 8) | ((0) & 0xFF))  -- CLC
      WHEN 12 THEN (((0) << 16) | ((((cpu.p) & 0xBF)) << 8) | ((0) & 0xFF))  -- CLV
      WHEN 13 THEN (((0) << 16) | (((((cpu.p) & 0x7D) | (CASE WHEN (s1) = 0 THEN 2 ELSE 0 END) | ((s1) & 0x80))) << 8) | ((s1) & 0xFF))  -- PLA
      WHEN 14 THEN (((0) << 16) | (((((cpu.p) & 0x7D) | (CASE WHEN (val) = 0 THEN 2 ELSE 0 END) | ((val) & 0x80))) << 8) | ((val) & 0xFF))  -- LDX
      WHEN 15 THEN (((0) << 16) | (((((cpu.p) & 0x7C) | (CASE WHEN ((((cpu.x) - (val)) & 0xFF)) = 0 THEN 2 ELSE 0 END) | (CASE WHEN (val) <= (cpu.x) THEN 1 ELSE 0 END) | (((((cpu.x) - (val)) & 0xFF)) & 0x80))) << 8) | ((0) & 0xFF))  -- CPX
      WHEN 16 THEN (((0) << 16) | ((cpu.p) << 8) | ((cpu.a) & 0xFF))  -- PHA
      WHEN 17 THEN (((0) << 16) | (((((cpu.p) & 0x7C) | (CASE WHEN ((((cpu.y) - (val)) & 0xFF)) = 0 THEN 2 ELSE 0 END) | (CASE WHEN (val) <= (cpu.y) THEN 1 ELSE 0 END) | (((((cpu.y) - (val)) & 0xFF)) & 0x80))) << 8) | ((0) & 0xFF))  -- CPY
      WHEN 18 THEN (((0) << 16) | ((cpu.p) << 8) | ((((cpu.p) | 0x30)) & 0xFF))  -- PHP
      WHEN 19 THEN (((0) << 16) | (((((cpu.p) & 0x7D) | (CASE WHEN ((((cpu.x) + 1) & 0xFF)) = 0 THEN 2 ELSE 0 END) | (((((cpu.x) + 1) & 0xFF)) & 0x80))) << 8) | (((((cpu.x) + 1) & 0xFF)) & 0xFF))  -- INX
      WHEN 20 THEN (((0) << 16) | ((cpu.p) << 8) | ((0) & 0xFF))  -- JMP
      WHEN 21 THEN (CASE WHEN (cpu.p) & 8 THEN (((0) << 16) | (((((cpu.p) & 0x3C) | (CASE WHEN ((cpu.a) - (val) + (((cpu.p) & 1)) - 1) >= 0 THEN 1 ELSE 0 END) | (CASE WHEN ((((cpu.a) - (val) + (((cpu.p) & 1)) - 1) & 0xFF)) = 0 THEN 2 ELSE 0 END) | ((((cpu.a) - (val) + (((cpu.p) & 1)) - 1)) & 0x80) | (CASE WHEN (((cpu.a) | (val)) & ~((cpu.a) & (val))) & (((cpu.a) | (((cpu.a) - (val) + (((cpu.p) & 1)) - 1))) & ~((cpu.a) & (((cpu.a) - (val) + (((cpu.p) & 1)) - 1)))) & 0x80 THEN 0x40 ELSE 0 END))) << 8) | ((((CASE WHEN (((cpu.a) & 0xF0) - ((val) & 0xF0) + (CASE WHEN (((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) < 0 THEN ((((((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) - 0x06) & 0x0F) - 0x10) ELSE (((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) END)) < 0 THEN ((((cpu.a) & 0xF0) - ((val) & 0xF0) + (CASE WHEN (((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) < 0 THEN ((((((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) - 0x06) & 0x0F) - 0x10) ELSE (((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) END)) - 0x60) ELSE (((cpu.a) & 0xF0) - ((val) & 0xF0) + (CASE WHEN (((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) < 0 THEN ((((((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) - 0x06) & 0x0F) - 0x10) ELSE (((cpu.a) & 0x0F) - ((val) & 0x0F) + (((cpu.p) & 1)) - 1) END)) END) & 0xFF)) & 0xFF)) ELSE (((0) << 16) | (((((cpu.p) & 0x3C) | (CASE WHEN ((cpu.a) - (val) + (((cpu.p) & 1)) - 1) >= 0 THEN 1 ELSE 0 END) | (CASE WHEN ((((cpu.a) - (val) + (((cpu.p) & 1)) - 1) & 0xFF)) = 0 THEN 2 ELSE 0 END) | ((((cpu.a) - (val) + (((cpu.p) & 1)) - 1)) & 0x80) | (CASE WHEN (((cpu.a) | (val)) & ~((cpu.a) & (val))) & (((cpu.a) | (((cpu.a) - (val) + (((cpu.p) & 1)) - 1))) & ~((cpu.a) & (((cpu.a) - (val) + (((cpu.p) & 1)) - 1)))) & 0x80 THEN 0x40 ELSE 0 END))) << 8) | (((((cpu.a) - (val) + (((cpu.p) & 1)) - 1) & 0xFF)) & 0xFF)) END)  -- SBC
