      WHEN 59 THEN (((0) << 16) | (((((cpu.p) & 0x3C) | (CASE WHEN (((((cpu.a) & (val)) >> 1) | (((cpu.p) & 1) << 7))) = 0 THEN 2 ELSE 0 END) | ((((((cpu.a) & (val)) >> 1) | (((cpu.p) & 1) << 7))) & 0x80) | (CASE WHEN (((((cpu.a) & (val)) >> 1) | (((cpu.p) & 1) << 7)) & 0x40) != 0 THEN 1 ELSE 0 END) | (CASE WHEN ((((((cpu.a) & (val)) >> 1) | (((cpu.p) & 1) << 7)) >> 6) & 1) != ((((((cpu.a) & (val)) >> 1) | (((cpu.p) & 1) << 7)) >> 5) & 1) THEN 0x40 ELSE 0 END))) << 8) | ((((((cpu.a) & (val)) >> 1) | (((cpu.p) & 1) << 7))) & 0xFF))  -- ARR
      WHEN 60 THEN (((0) << 16) | (((((cpu.p) & 0x7D) | (CASE WHEN ((((cpu.a) | 0xEE) & (cpu.x) & (val))) = 0 THEN 2 ELSE 0 END) | (((((cpu.a) | 0xEE) & (cpu.x) & (val))) & 0x80))) << 8) | (((((cpu.a) | 0xEE) & (cpu.x) & (val))) & 0xFF))  -- XAA
      WHEN 61 THEN (((0) << 16) | (((((cpu.p) & 0x7D) | (CASE WHEN (((cpu.a) & (val))) = 0 THEN 2 ELSE 0 END) | ((((cpu.a) & (val))) & 0x80))) << 8) | ((((cpu.a) & (val))) & 0xFF))  -- LXA
      WHEN 62 THEN (((0) << 16) | (((((cpu.p) & 0x7C) | (CASE WHEN (((((cpu.a) & (cpu.x)) - (val)) & 0xFF)) = 0 THEN 2 ELSE 0 END) | (CASE WHEN (val) <= ((cpu.a) & (cpu.x)) THEN 1 ELSE 0 END) | ((((((cpu.a) & (cpu.x)) - (val)) & 0xFF)) & 0x80))) << 8) | ((((((cpu.a) & (cpu.x)) - (val)) & 0xFF)) & 0xFF))  -- SBX
      WHEN 63 THEN (((0) << 16) | (((((cpu.p) & 0x7D) | (CASE WHEN (((cpu.s) & (val))) = 0 THEN 2 ELSE 0 END) | ((((cpu.s) & (val))) & 0x80))) << 8) | ((((cpu.s) & (val))) & 0xFF))  -- LAS
      WHEN 64 THEN (((0) << 16) | ((cpu.p) << 8) | ((((cpu.a) & (cpu.x) & (((((ea) - (cpu.y)) & 0xFFFF) >> 8) + 1))) & 0xFF))  -- SHA
      WHEN 65 THEN (((0) << 16) | ((cpu.p) << 8) | ((((cpu.x) & (((((ea) - (cpu.y)) & 0xFFFF) >> 8) + 1))) & 0xFF))  -- SHX
      WHEN 66 THEN (((0) << 16) | ((cpu.p) << 8) | ((((cpu.y) & (((((ea) - (cpu.x)) & 0xFFFF) >> 8) + 1))) & 0xFF))  -- SHY
      WHEN 67 THEN (((((cpu.a) & (cpu.x) & (((((ea) - (cpu.y)) & 0xFFFF) >> 8) + 1))) << 16) | ((cpu.p) << 8) | ((((cpu.a) & (cpu.x))) & 0xFF))  -- TAS
      WHEN 68 THEN (((0) << 16) | ((cpu.p) << 8) | ((0) & 0xFF))  -- KIL
    END AS res,
        CASE ctl
      WHEN 0 THEN ((cpu.pc + len) & 0xFFFF)  -- fall through
      WHEN 12 THEN (CASE WHEN (cpu.p & 0x02) = 0 THEN ea ELSE ((cpu.pc + 2) & 0xFFFF) END)  -- BNE
      WHEN 13 THEN (CASE WHEN (cpu.p & 0x02) != 0 THEN ea ELSE ((cpu.pc + 2) & 0xFFFF) END)  -- BEQ
      WHEN 1 THEN ea  -- JMP, JSR
      WHEN 3 THEN (((s1 | (s2 << 8)) + 1) & 0xFFFF)  -- RTS
      WHEN 10 THEN (CASE WHEN (cpu.p & 0x01) = 0 THEN ea ELSE ((cpu.pc + 2) & 0xFFFF) END)  -- BCC
      WHEN 11 THEN (CASE WHEN (cpu.p & 0x01) != 0 THEN ea ELSE ((cpu.pc + 2) & 0xFFFF) END)  -- BCS
      WHEN 6 THEN (CASE WHEN (cpu.p & 0x80) = 0 THEN ea ELSE ((cpu.pc + 2) & 0xFFFF) END)  -- BPL
      WHEN 7 THEN (CASE WHEN (cpu.p & 0x80) != 0 THEN ea ELSE ((cpu.pc + 2) & 0xFFFF) END)  -- BMI
      WHEN 8 THEN (CASE WHEN (cpu.p & 0x40) = 0 THEN ea ELSE ((cpu.pc + 2) & 0xFFFF) END)  -- BVC
      WHEN 9 THEN (CASE WHEN (cpu.p & 0x40) != 0 THEN ea ELSE ((cpu.pc + 2) & 0xFFFF) END)  -- BVS
      WHEN 4 THEN (s2 | (s3 << 8))  -- RTI
      WHEN 2 THEN ea  -- BRK: the vector
      WHEN 5 THEN cpu.pc  -- KIL: park on the instruction
    END AS npc
      FROM (
        SELECT cpu.pc AS ipc, m0.v AS op, d.len, d.mode, d.kind, d.dst, d.sp, d.ctl, d.wr,
          w.io_lo, w.io_hi, w.wr_lo, w.wr_hi,
          CASE d.mode
      WHEN 3 THEN m1.v  -- zp
      WHEN 6 THEN (m1.v | (m2.v << 8))  -- abs
      WHEN 4 THEN ((m1.v + cpu.x) & 0xFF)  -- zp,x
      WHEN 7 THEN (((m1.v | (m2.v << 8)) + cpu.x) & 0xFFFF)  -- abs,x
      WHEN 8 THEN (((m1.v | (m2.v << 8)) + cpu.y) & 0xFFFF)  -- abs,y
      WHEN 10 THEN (((pl.v | (ph.v << 8)) + cpu.y) & 0xFFFF)  -- (zp),y
      WHEN 9 THEN (pl.v | (ph.v << 8))  -- (zp,x)
      WHEN 11 THEN ((cpu.pc + 2 + ((m1.v & 0x7F) - (m1.v & 0x80))) & 0xFFFF)  -- branch target
      WHEN 5 THEN ((m1.v + cpu.y) & 0xFF)  -- zp,y
      WHEN 12 THEN (pl.v | (ph.v << 8))  -- JMP (ind)
      WHEN 13 THEN (pl.v | (ph.v << 8))  -- the BRK vector
    END AS ea,
          CASE d.mode WHEN 2 THEN m1.v WHEN 1 THEN cpu.a ELSE mv.v END AS val,
          st1.v AS s1, st2.v AS s2, st3.v AS s3
        FROM memory m0
          JOIN decode d ON d.op = m0.v
          JOIN watch w ON w.id = 1
          JOIN memory m1 ON m1.addr = ((cpu.pc + 1) & 0xFFFF)
          JOIN memory m2 ON m2.addr = ((cpu.pc + 2) & 0xFFFF)
          LEFT JOIN memory pl ON pl.addr = CASE d.mode
      WHEN 10 THEN m1.v  -- (zp),y
      WHEN 9 THEN ((m1.v + cpu.x) & 0xFF)  -- (zp,x)
      WHEN 12 THEN (m1.v | (m2.v << 8))  -- JMP (ind)
      WHEN 13 THEN 0xFFFE  -- BRK vector
    END
          LEFT JOIN memory ph ON ph.addr = CASE d.mode
      WHEN 10 THEN ((m1.v + 1) & 0xFF)  -- (zp),y wraps in page zero
      WHEN 9 THEN ((m1.v + cpu.x + 1) & 0xFF)  -- (zp,x) wraps in page zero
      WHEN 12 THEN (((m1.v | (m2.v << 8)) & 0xFF00) | ((m1.v + 1) & 0xFF))  -- JMP (ind) never crosses a page
      WHEN 13 THEN 0xFFFF  -- BRK vector
    END
          LEFT JOIN memory mv ON mv.addr = CASE WHEN d.reads THEN CASE d.mode
      WHEN 3 THEN m1.v  -- zp
      WHEN 6 THEN (m1.v | (m2.v << 8))  -- abs
      WHEN 4 THEN ((m1.v + cpu.x) & 0xFF)  -- zp,x
      WHEN 7 THEN (((m1.v | (m2.v << 8)) + cpu.x) & 0xFFFF)  -- abs,x
      WHEN 8 THEN (((m1.v | (m2.v << 8)) + cpu.y) & 0xFFFF)  -- abs,y
      WHEN 10 THEN (((pl.v | (ph.v << 8)) + cpu.y) & 0xFFFF)  -- (zp),y
      WHEN 9 THEN (pl.v | (ph.v << 8))  -- (zp,x)
      WHEN 11 THEN ((cpu.pc + 2 + ((m1.v & 0x7F) - (m1.v & 0x80))) & 0xFFFF)  -- branch target
      WHEN 5 THEN ((m1.v + cpu.y) & 0xFF)  -- zp,y
      WHEN 12 THEN (pl.v | (ph.v << 8))  -- JMP (ind)
      WHEN 13 THEN (pl.v | (ph.v << 8))  -- the BRK vector
    END END
          LEFT JOIN memory st1 ON st1.addr = CASE WHEN d.sp >= 1 THEN 0x100 + ((cpu.s + 1) & 0xFF) END
          LEFT JOIN memory st2 ON st2.addr = CASE WHEN d.sp >= 2 THEN 0x100 + ((cpu.s + 2) & 0xFF) END
          LEFT JOIN memory st3 ON st3.addr = CASE WHEN d.sp >= 3 THEN 0x100 + ((cpu.s + 3) & 0xFF) END
        WHERE m0.addr = cpu.pc
      ) g
    ) f
  ) WHERE halted = 0 AND hit IS NULL;
  UPDATE OR FAIL memory SET v = (SELECT w0v FROM cpu) WHERE addr = (SELECT w0a FROM cpu);
  UPDATE OR FAIL memory SET v = (SELECT w1v FROM cpu) WHERE addr = (SELECT w1a FROM cpu);
  UPDATE OR FAIL memory SET v = (SELECT w2v FROM cpu) WHERE addr = (SELECT w2a FROM cpu);
  -- applied: clear the slots, so ticks that find the latch halted or tripped do nothing
  UPDATE OR FAIL cpu SET w0a = NULL, w0v = NULL, w1a = NULL, w1v = NULL, w2a = NULL, w2v = NULL WHERE w0a IS NOT NULL;
  SELECT RAISE(IGNORE);   -- the clock is a signal, not a record
END;
